import{_ as e,o as a,c as i,an as l}from"./chunks/framework.BjfRDIIO.js";const y=JSON.parse('{"title":"Outputs","description":"","frontmatter":{},"headers":[],"relativePath":"manual/outputs.md","filePath":"manual/outputs.md","lastUpdated":null}'),s={name:"manual/outputs.md"};function d(r,t,o,n,c,p){return a(),i("div",null,[...t[0]||(t[0]=[l(`<h1 id="Outputs" tabindex="-1">Outputs <a class="header-anchor" href="#Outputs" aria-label="Permalink to &quot;Outputs {#Outputs}&quot;">​</a></h1><p><code>solve</code> returns a <code>RasterStack</code>: one layer per output variable, all on the same spatial and time dimensions.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Dimension</th><th style="text-align:left;">In</th><th style="text-align:left;">Values</th></tr></thead><tbody><tr><td style="text-align:left;"><code>point</code></td><td style="text-align:left;">a <a href="/MicroclimateMapper.jl/previews/PR39/api#MicroclimateMapper.MicroVectorProblem"><code>MicroVectorProblem</code></a></td><td style="text-align:left;">the <code>(longitude, latitude)</code> of each point</td></tr><tr><td style="text-align:left;"><code>X</code>, <code>Y</code></td><td style="text-align:left;">a <a href="/MicroclimateMapper.jl/previews/PR39/api#MicroclimateMapper.MicroRasterProblem"><code>MicroRasterProblem</code></a></td><td style="text-align:left;">the run&#39;s grid</td></tr><tr><td style="text-align:left;"><code>Ti</code></td><td style="text-align:left;">all</td><td style="text-align:left;">the hours solved: every hour of every day for daily data, every hour of 12 representative days for monthly</td></tr><tr><td style="text-align:left;"><code>depth</code></td><td style="text-align:left;">soil layers</td><td style="text-align:left;">the <code>depths</code> of the <code>MicroModel</code></td></tr><tr><td style="text-align:left;"><code>height</code></td><td style="text-align:left;">air layers</td><td style="text-align:left;">the <code>heights</code> of the <code>MicroModel</code></td></tr></tbody></table><p>Cells outside an <code>area</code> polygon, or with no data, are <code>missing</code>.</p><h2 id="Layers" tabindex="-1">Layers <a class="header-anchor" href="#Layers" aria-label="Permalink to &quot;Layers {#Layers}&quot;">​</a></h2><p>Which layers are written is set by <code>output_layers</code> of the <a href="/MicroclimateMapper.jl/previews/PR39/api#MicroclimateMapper.MicroMapModel"><code>MicroMapModel</code></a>, a tuple of <a href="/MicroclimateMapper.jl/previews/PR39/api#MicroclimateMapper.LayerSpec"><code>LayerSpec</code></a>s. Each names a field of Microclimate.jl&#39;s result and says what kind it is:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Kind</th><th style="text-align:left;">Shape per point or cell</th><th style="text-align:left;">Default layers</th></tr></thead><tbody><tr><td style="text-align:left;"><code>:soil</code></td><td style="text-align:left;">time × depth</td><td style="text-align:left;"><code>soil_temperature</code>, <code>soil_moisture</code></td></tr><tr><td style="text-align:left;"><code>:profile</code></td><td style="text-align:left;">time × height</td><td style="text-align:left;"><code>air_temperature</code>, <code>relative_humidity</code>, <code>wind_speed</code></td></tr><tr><td style="text-align:left;"><code>:scalar</code></td><td style="text-align:left;">time</td><td style="text-align:left;"><code>global_radiation</code>, <code>sky_temperature</code>, <code>snow_depth</code>, <code>ground_surface_water</code>, <code>ground_dew</code>, <code>ground_frost</code>, <code>ground_standing_dew</code>, <code>ground_standing_frost</code></td></tr><tr><td style="text-align:left;"><code>:canopy</code></td><td style="text-align:left;">time × canopy layer</td><td style="text-align:left;">none by default; with a multilayer canopy, e.g. <code>LayerSpec(:leaf_temperature, :canopy)</code></td></tr></tbody></table><p>Writing fewer layers saves memory, which limits grid size before time does:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">model </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> MicroMapModel</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(; micro_model, dem_source </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> SRTM, weather_source </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> CRUCL2,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    output_layers </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">LayerSpec</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">:soil_temperature</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">:soil</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">), </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">LayerSpec</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">:snow_depth</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">:scalar</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)))</span></span></code></pre></div><p>Where two kinds share a field name, a third argument names the field and the first names the layer: <code>LayerSpec(:canopy_air_temperature, :canopy, :air_temperature)</code>.</p><h2 id="Units" tabindex="-1">Units <a class="header-anchor" href="#Units" aria-label="Permalink to &quot;Units {#Units}&quot;">​</a></h2><p>Every layer carries units. For writing to NetCDF or another format without units, <a href="/MicroclimateMapper.jl/previews/PR39/api#MicroclimateMapper.strip_to_canonical"><code>strip_to_canonical</code></a> converts each layer to the unit given by <a href="/MicroclimateMapper.jl/previews/PR39/api#MicroclimateMapper.canonical_unit"><code>canonical_unit</code></a> and strips it:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">write</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;run.nc&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">strip_to_canonical</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(output))</span></span></code></pre></div><table tabindex="0"><thead><tr><th style="text-align:left;">Layers</th><th style="text-align:left;">Canonical unit</th></tr></thead><tbody><tr><td style="text-align:left;">temperatures</td><td style="text-align:left;">°C</td></tr><tr><td style="text-align:left;"><code>soil_moisture</code></td><td style="text-align:left;">m³ m⁻³</td></tr><tr><td style="text-align:left;"><code>relative_humidity</code></td><td style="text-align:left;">%</td></tr><tr><td style="text-align:left;"><code>wind_speed</code></td><td style="text-align:left;">m s⁻¹</td></tr><tr><td style="text-align:left;"><code>global_radiation</code></td><td style="text-align:left;">W m⁻²</td></tr><tr><td style="text-align:left;"><code>snow_depth</code></td><td style="text-align:left;">cm</td></tr><tr><td style="text-align:left;">water at the surface, dew and frost</td><td style="text-align:left;">kg m⁻²</td></tr></tbody></table><h2 id="Solar-radiation" tabindex="-1">Solar radiation <a class="header-anchor" href="#Solar-radiation" aria-label="Permalink to &quot;Solar radiation {#Solar-radiation}&quot;">​</a></h2><p><code>solar_output_layers</code> adds layers of solar radiation, alongside the microclimate or, with <code>solar_only = true</code>, instead of it. Each is a <a href="/MicroclimateMapper.jl/previews/PR39/api#MicroclimateMapper.SolarOutputLayer"><code>SolarOutputLayer</code></a>: a component (global, direct or diffuse on a horizontal surface, or global on the sloping surface of the cell) and optionally a waveband. Four are predefined:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Constant</th><th style="text-align:left;">Layer</th><th style="text-align:left;">Waveband</th></tr></thead><tbody><tr><td style="text-align:left;"><a href="/MicroclimateMapper.jl/previews/PR39/api#MicroclimateMapper.SOLAR_BROADBAND"><code>SOLAR_BROADBAND</code></a></td><td style="text-align:left;"><code>global_radiation</code></td><td style="text-align:left;">all</td></tr><tr><td style="text-align:left;"><a href="/MicroclimateMapper.jl/previews/PR39/api#MicroclimateMapper.SOLAR_PAR"><code>SOLAR_PAR</code></a></td><td style="text-align:left;"><code>par</code></td><td style="text-align:left;">400–700 nm</td></tr><tr><td style="text-align:left;"><a href="/MicroclimateMapper.jl/previews/PR39/api#MicroclimateMapper.SOLAR_UVB"><code>SOLAR_UVB</code></a></td><td style="text-align:left;"><code>uv_b</code></td><td style="text-align:left;">290–315 nm</td></tr><tr><td style="text-align:left;"><a href="/MicroclimateMapper.jl/previews/PR39/api#MicroclimateMapper.SOLAR_NIR"><code>SOLAR_NIR</code></a></td><td style="text-align:left;"><code>nir</code></td><td style="text-align:left;">700–4000 nm</td></tr></tbody></table><p>Wavebands come from the spectral model of SolarRadiation.jl, see its <a href="https://biophysicalecology.github.io/SolarRadiation.jl/dev/manual/atmosphere" target="_blank" rel="noreferrer">Atmosphere</a> page.</p>`,18)])])}const g=e(s,[["render",d]]);export{y as __pageData,g as default};
